def main(delta, *args):
    dates = []
    for string in args:
        if '-' in string:
            dates.append(datetime.strptime(string, '%d-%m-%Y') + timedelta(days=delta))
        elif '/' in string:
            dates.append(datetime.strptime(string, '%d/%m/%Y') + timedelta(days=delta))
        else:
            dates.append(None)
    return [date for date in dates if type(date) != None]
